using System;using System.IO;using System.Linq;using System.Reflection;using System.Globalization;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Runtime.CompilerServices;
class OptionBoundaryProbe {
 class TextInput {public string Value;public int Calls;public int Mode;public override string ToString(){Calls++;if(Mode==1)throw new InvalidOperationException("CURRENT_ONLY_CONVERSION");return Mode==2?null:Value;}}
 struct BoxedText {public int Calls;public override string ToString(){Calls++;return "pooled";}}
 static object Outcome(MethodInfo method,object arg,object[] tail,bool control){string wrapper=null,error=null,message=null;object result=null;try{object first=arg;if(control){string name=arg==null?"":arg.GetType().FullName;first=arg==null||name=="ExcelDna.Integration.ExcelMissing"||name=="ExcelDna.Integration.ExcelEmpty"?null:Convert.ToString(RuntimeHelpers.GetObjectValue(arg)).Trim();}result=method.Invoke(null,new[]{first}.Concat(tail).ToArray());}catch(Exception e){wrapper=e.GetType().FullName;while(e is TargetInvocationException&&e.InnerException!=null)e=e.InnerException;error=e.GetType().FullName;message=e.Message;}return new{result_type=result==null?null:result.GetType().FullName,result_text=result==null?null:Convert.ToString(result,CultureInfo.InvariantCulture),enum_bits=result!=null&&result.GetType().IsEnum?Convert.ToInt64(result).ToString(CultureInfo.InvariantCulture):null,actual_exception=error,message=message,reflection_wrapper=wrapper,conversion_calls=arg is TextInput?((TextInput)arg).Calls:(arg is BoxedText?((BoxedText)arg).Calls:0)};}
 static string Comparable(object obj){var j=new JavaScriptSerializer();var d=j.Deserialize<Dictionary<string,object>>(j.Serialize(obj));d.Remove("reflection_wrapper");return j.Serialize(d);}
 static void Main(string[] args){var json=new JavaScriptSerializer{MaxJsonLength=int.MaxValue};var packet=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(args[1]));var host=Assembly.LoadFrom(Path.Combine(args[0],"BESHStatNG.dll"));var common=Assembly.LoadFrom(Path.Combine(args[0],"BESHStat.Excel.Common.dll"));var rows=new List<object>();int differences=0;foreach(string culture in new[]{"","sk-SK"}){CultureInfo.CurrentCulture=culture==""?CultureInfo.InvariantCulture:new CultureInfo(culture);CultureInfo.CurrentUICulture=CultureInfo.CurrentCulture;foreach(Dictionary<string,object> spec in (object[])packet["rows"]){string name=(string)spec["name"];var native=host.GetType((string)spec["native_owner"]).GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public);var portable=common.GetType((string)spec["common_owner"]).GetMethod(name,BindingFlags.Public|BindingFlags.Static);var tails=new List<object[]>{new object[0]};foreach(var p in native.GetParameters().Skip(1)){object[] values=p.ParameterType==typeof(bool)?new object[]{false,true}:p.ParameterType==typeof(string)?new object[]{null,"CURRENT_DEFAULT"}:p.ParameterType.IsEnum?Enum.GetValues(p.ParameterType).Cast<object>().ToArray():new object[]{p.DefaultValue};tails=tails.SelectMany(t=>values.Select(v=>t.Concat(new[]{v}).ToArray())).ToList();}var inputs=new List<Func<object>>{()=>null,()=>"",()=>"  ",()=>"CURRENT_INVALID",()=>"\0",()=>"\u00ad",()=>"_",()=>1.25,()=>DBNull.Value,()=>new TextInput{Value="pooled"},()=>new TextInput{Mode=1},()=>new TextInput{Mode=2},()=>new BoxedText()};foreach(string choice in ((object[])spec["choices"]).Cast<string>().Distinct()){string c=choice;inputs.Add(()=>c);inputs.Add(()=>" "+c.ToLowerInvariant()+" ");}int id=0;foreach(var tail in tails)foreach(var factory in inputs){object a=factory(),b=factory();object n=Outcome(native,a,tail,false),p=Outcome(portable,b,tail,true);bool same=Comparable(n)==Comparable(p);if(!same)differences++;rows.Add(new{method=name,culture=culture==""?"Invariant":culture,id=id++,tail=tail.Select(x=>x==null?null:Convert.ToString(x,CultureInfo.InvariantCulture)).ToArray(),native=n,control=p,exact=same});}}}File.WriteAllText(args[2],json.Serialize(new{classification="CURRENT_ONLY_NOT_ARCHIVED_REFERENCE",methods=30,cases=rows,comparisons=rows.Count,differences=differences,comparison_fields="Result type/text/enum bits, actual exception type/message, conversion count and boxed source state; reflection wrappers recorded separately because control conversion precedes reflective call",original_calls=0}));if(differences!=0)Environment.Exit(1);}
}
